% Declare credit score and income for Priya and Sam
enum Person = {Priya, Sam};
array[Person] of int: creditScore = [680, 750];
int: combinedIncome = 9000;
int: combinedDebt = 3200;
int: requestedLoanAmount; % this will represent the unspecified requested loan amount

% DTI calculation
int: DTI = combinedDebt * 100 div combinedIncome; % DTI as a percentage

% Constraints
var int: creditTier = min(creditScore[Priya], creditScore[Sam]);

% Loan outcome evaluation
var string: outcome;

constraint 
    % Rule 1: Check credit tier
    (creditTier >= 600) /\
    % Rule 2: Check DTI
    (DTI <= 43) /\
    % Rule 3: Loan approval check (this will evaluate the logic for approval and counter-offer)
    (if requestedLoanAmount <= combinedIncome * 0.43 then outcome = "Approved"
     else outcome = "Counter-Offer";);

% Output decision result
constraint
    (outcome = "Counter-Offer" \/ outcome = "Approved");

