enum ANIMAL = {tortoise, parrot, goat, rabbit, wolf};
array[1..5] of var ANIMAL: animals;

% Constraints from the clues
constraint animals[1] = tortoise;
constraint animals[2] = parrot;
constraint animals[3] = goat;

% The rabbit must be in a lower-numbered pen than the wolf
constraint exists(i in 1..5)(exists(j in (i+1)..5)(animals[i] = rabbit /\ animals[j] = wolf));

% The wolf preys on the rabbit (ensured by their positions)
constraint forall(i in 1..5)(if animals[i] = wolf then (exists(j in 1..5)(animals[j] = rabbit /\ j < i)) else true endif);

% Ensure that all animals are placed
constraint alldifferent(animals);

solve satisfy;
